// CONNECTING TO AN INSTITUTION — the credential model, and the policy that decides what to try next.
//
// This is the layer where a bug costs more than a wrong number. A retry loop against a bank login
// does not produce a bad answer; it produces a FROZEN ACCOUNT, and a frozen account costs days of
// phone calls and blocks every capability downstream of it. So the safety properties are the design,
// and the arithmetic is incidental:
//
//  1. AN AUTH FAILURE IS NEVER RETRIED. Not once, not after a delay. One rejection can be a typo or a
//     changed password; a second automated attempt is how lockout happens, and the difference
//     between "I could not sync today" and "I cannot log in at all" is not close. A TRANSPORT
//     failure — the institution was not reached — is a different thing entirely and IS retried.
//     Collapsing those two into "it failed" is the mistake this module exists to not make.
//
//  2. MFA IS A HANDOFF, NOT AN OBSTACLE. A challenge parks the run and asks the person. Nothing here
//     tries to route around one: it is futile, and attempting it is itself the anomaly signal that
//     gets a session flagged.
//
//  3. A FRESH SESSION IS THE WHOLE WIN. Reusing stored cookies means authenticating once and fetching
//     for weeks. Fewer logins is fewer challenges is less to go wrong — session reuse is not an
//     optimisation here, it is the primary lockout-avoidance mechanism.
//
//  4. FILE-DROP IS ALWAYS AVAILABLE AND ALWAYS LAST. Every automated path against a site somebody
//     else controls will break, usually without warning. A system that only works while the
//     automation works is a system that stops working, so the manual path is never removed — and
//     when everything else is blocked, that is the answer this gives rather than an error.
//
// THE SECRET NEVER ENTERS THIS MODULE. A `CredentialRef` is an ID into `bsc secret`, whose contract
// is that no verb reads a value back; the value lives in the OS keychain and is fetched by whatever
// actually types it, at the last possible moment. Nothing here holds, returns, logs or serialises
// one, and `containsSecretBearingKey` is the guard that keeps it that way.
export type AuthKind = "password" | "password-mfa" | "oauth";

/** How data can actually be got out, in preference order. */
export type Capability =
  /** Drive to the institution's own export button and take the file. ROBUST — the file is a
   *  contract they maintain, where the DOM is not. */
  | "export-download"
  /** Read the transactions table. BRITTLE: a layout change breaks it silently and it is far more
   *  visible to whatever watches for automation. */
  | "dom-scrape"
  /** A person downloads it and drops it in. Always available, never removed. */
  | "file-drop";

/**
 * A reference to a credential, never the credential.
 *
 * `secretId` is a `bsc secret` id. The account is not secret but IS personal, so it is masked
 * wherever this is rendered.
 */
export interface CredentialRef {
  readonly secretId: string;
  readonly account: string;
}

export interface InstitutionConnector {
  readonly id: string;
  readonly institution: string;
  readonly auth: AuthKind;
  /** Preference order. `file-drop` is last and always present. */
  readonly capabilities: readonly Capability[];
  readonly loginUrl: string;
  /** Where the export lives, in words, for the person doing it by hand. */
  readonly exportPath: string;
  /** The ingest profile that reads what this produces. */
  readonly profileId: string;
  /** FALSE until somebody has actually driven this end to end. */
  readonly verified: boolean;
  readonly caveat?: string;
}

export type AttemptOutcome =
  /** Signed in and got what we came for. */
  | "ok"
  /** The institution was NOT REACHED — DNS, timeout, connection reset. Says nothing about the
   *  credential, and is the only outcome that may be retried automatically. */
  | "transport"
  /** The credential was REJECTED. Never retried. */
  | "auth"
  /** MFA, a device check, a security question. A person is needed. */
  | "challenge"
  /** Signed in, but the page is not the page we expected — a redesign, or an interstitial. */
  | "layout"
  /** The institution says the account is locked. Only a person can clear this. */
  | "locked";

export interface AttemptRecord {
  /** `YYYY-MM-DDTHH:MM:SSZ`. */
  readonly at: string;
  readonly outcome: AttemptOutcome;
  /** Free text for a person. NEVER a credential — see `containsSecretBearingKey`. */
  readonly detail?: string;
}

export interface ConnectionState {
  readonly connectorId: string;
  /** Most recent LAST. */
  readonly attempts: readonly AttemptRecord[];
  /** When the stored session was established, if there is one. */
  readonly sessionSince?: string;
  /** Set by a person, cleared by a person. Nothing automated writes this to false. */
  readonly lockedOut: boolean;
}

export type NextAction =
  | { readonly kind: "use-session"; readonly why: string }
  | { readonly kind: "login"; readonly why: string }
  | { readonly kind: "wait"; readonly untilMinutes: number; readonly why: string }
  | { readonly kind: "hand-to-person"; readonly why: string; readonly instead: Capability }
  | { readonly kind: "stop"; readonly why: string; readonly instead: Capability };

export interface PolicyOptions {
  /** How long stored cookies are assumed good for. */
  readonly sessionTtlHours?: number;
  /** How many CONSECUTIVE transport failures before backing right off. */
  readonly maxTransportRetries?: number;
  /** The first backoff step; it doubles. */
  readonly backoffBaseMinutes?: number;
  readonly backoffCapMinutes?: number;
  /** Minimum gap between two logins, however healthy things look. */
  readonly loginCooldownMinutes?: number;
}

const minutesBetween = (a: string, b: string): number =>
  (Date.parse(b) - Date.parse(a)) / 60_000;

/** Consecutive attempts at the end of the list sharing one outcome. */
export function trailing(state: ConnectionState, outcome: AttemptOutcome): number {
  let n = 0;
  for (let i = state.attempts.length - 1; i >= 0; i--) {
    if (state.attempts[i].outcome !== outcome) break;
    n++;
  }
  return n;
}

export const lastAttempt = (s: ConnectionState): AttemptRecord | undefined => s.attempts[s.attempts.length - 1];

/** A stored session is worth using while it is young. This is the lockout-avoidance mechanism. */
export function sessionIsFresh(state: ConnectionState, asOf: string, ttlHours: number): boolean {
  if (!state.sessionSince) return false;
  const age = minutesBetween(state.sessionSince, asOf);
  return age >= 0 && age < ttlHours * 60;
}

/** Doubling backoff, capped. */
export function backoff(consecutive: number, baseMinutes: number, capMinutes: number): number {
  return Math.min(capMinutes, baseMinutes * 2 ** Math.max(0, consecutive - 1));
}

/**
 * What to do next, and the order of the rules IS the safety.
 *
 * Everything that stops is checked before anything that acts, so no amount of session freshness or
 * elapsed time can talk this into retrying a rejected credential.
 */
export function decide(
  connector: InstitutionConnector,
  state: ConnectionState,
  asOf: string,
  opts: PolicyOptions = {},
): NextAction {
  const {
    sessionTtlHours = 168,
    maxTransportRetries = 3,
    backoffBaseMinutes = 5,
    backoffCapMinutes = 240,
    loginCooldownMinutes = 15,
  } = opts;

  if (state.lockedOut) {
    return {
      kind: "stop",
      why: "the account is locked — only a call to the institution clears that, and nothing here will try again in the meantime",
      instead: "file-drop",
    };
  }

  const last = lastAttempt(state);

  if (last?.outcome === "locked") {
    return {
      kind: "stop",
      why: "the institution reported the account locked on the last attempt — clear it with them before anything else touches this",
      instead: "file-drop",
    };
  }

  if (last?.outcome === "auth") {
    // NEVER AUTOMATICALLY. One rejection can be a typo or a rotated password; a second attempt is
    // how a lockout happens, and "I could not sync today" and "I cannot log in at all" are not
    // remotely the same cost.
    return {
      kind: "stop",
      why: "the credential was rejected — a second automated attempt is how an account gets locked, so this stops here. Update the secret with `bsc secret put` and clear the attempt.",
      instead: "file-drop",
    };
  }

  if (last?.outcome === "challenge") {
    return {
      kind: "hand-to-person",
      why: "a verification challenge is waiting — nothing here will try to route around one, because attempting that is itself what gets a session flagged",
      instead: "file-drop",
    };
  }

  if (last?.outcome === "layout") {
    return {
      kind: "stop",
      why: `signed in, but the page was not what ${connector.institution} served last time — a scrape against a changed layout reads plausible nonsense, so it stops rather than guessing`,
      instead: "file-drop",
    };
  }

  const failures = trailing(state, "transport");
  if (failures >= maxTransportRetries) {
    return {
      kind: "wait",
      untilMinutes: backoff(failures, backoffBaseMinutes, backoffCapMinutes),
      why: `${failures} consecutive transport failures — the institution is not being reached, and hammering it is both useless and conspicuous`,
    };
  }
  if (failures > 0) {
    return {
      kind: "wait",
      untilMinutes: backoff(failures, backoffBaseMinutes, backoffCapMinutes),
      why: `${failures} transport failure(s) — the institution was not reached, which says nothing about the credential, so this retries after a pause`,
    };
  }

  if (sessionIsFresh(state, asOf, sessionTtlHours)) {
    return {
      kind: "use-session",
      why: "a stored session is still young — reusing it is what avoids the login, and avoiding the login is what avoids the challenge",
    };
  }

  const lastLogin = [...state.attempts].reverse().find((a) => a.outcome === "ok" || a.outcome === "challenge");
  if (lastLogin && minutesBetween(lastLogin.at, asOf) < loginCooldownMinutes) {
    return {
      kind: "wait",
      untilMinutes: Math.ceil(loginCooldownMinutes - minutesBetween(lastLogin.at, asOf)),
      why: "a login happened moments ago — repeated sign-ins in a short window are the pattern that draws attention",
    };
  }

  return { kind: "login", why: "no usable session, nothing blocking, and the cooldown has passed" };
}

/** The capability to actually use, given what the policy decided. */
export function capabilityFor(connector: InstitutionConnector, action: NextAction): Capability {
  if (action.kind === "stop" || action.kind === "hand-to-person") return action.instead;
  return connector.capabilities[0];
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Keeping the secret out

const SECRET_KEYS = /^(pass(word|phrase)?|secret|token|api[-_]?key|pin|otp|mfa|answer|cookie|session[-_]?id|authorization|credentials?)$/i;

/**
 * Whether any key ANYWHERE in an object is secret-bearing — the same discipline `bsc secret set`
 * enforces on its own payloads, applied to anything this layer would persist or print.
 *
 * A guard rather than a filter, deliberately: silently stripping a password would let a caller keep
 * writing code that puts one there.
 */
export function containsSecretBearingKey(value: unknown, seen = new Set<unknown>()): string | undefined {
  if (value === null || typeof value !== "object") return undefined;
  if (seen.has(value)) return undefined;
  seen.add(value);
  if (Array.isArray(value)) {
    for (const v of value) {
      const hit = containsSecretBearingKey(v, seen);
      if (hit) return hit;
    }
    return undefined;
  }
  for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
    if (SECRET_KEYS.test(k)) return k;
    const hit = containsSecretBearingKey(v, seen);
    if (hit) return hit;
  }
  return undefined;
}

/** An account identifier, masked for anything a person or a log will see. */
export function maskAccount(account: string): string {
  const at = account.indexOf("@");
  if (at > 0) return `${account[0]}${"*".repeat(Math.max(1, at - 1))}${account.slice(at)}`;
  if (account.length <= 4) return "*".repeat(account.length);
  return `${"*".repeat(account.length - 4)}${account.slice(-4)}`;
}

/** One line about a connection, safe to print. */
export const describe = (connector: InstitutionConnector, cred: CredentialRef, action: NextAction): string =>
  `${connector.institution} (${maskAccount(cred.account)}) → ${action.kind}: ${action.why}`;

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// The packaged connectors

/**
 * The four institutions asked for. EVERY ONE IS UNVERIFIED — nobody has driven these end to end —
 * and `export-download` leads every list because the file is a contract the institution maintains
 * while the DOM is not.
 */
export const CONNECTORS: readonly InstitutionConnector[] = [
  {
    id: "discover",
    institution: "Discover",
    auth: "password-mfa",
    capabilities: ["export-download", "file-drop"],
    loginUrl: "https://www.discover.com/",
    exportPath: "Account → Statements & Activity → Download Transactions (CSV)",
    profileId: "discover",
    verified: false,
    caveat: "expect a device-verification challenge on a browser profile it has not seen before",
  },
  {
    id: "capital-one",
    institution: "Capital One",
    auth: "password-mfa",
    capabilities: ["export-download", "file-drop"],
    loginUrl: "https://www.capitalone.com/",
    exportPath: "Account → View Transactions → Download (CSV)",
    profileId: "capital-one",
    verified: false,
    caveat: "the download is behind a date-range picker; a default range is not the range you want",
  },
  {
    id: "bank-of-america",
    institution: "Bank of America",
    auth: "password-mfa",
    capabilities: ["export-download", "file-drop"],
    loginUrl: "https://www.bankofamerica.com/",
    exportPath: "Account → Statements & Documents → Download (Microsoft Excel / CSV)",
    profileId: "bank-of-america",
    verified: false,
    caveat: "the CSV carries a summary block ABOVE the header row — the ingest profile says the same",
  },
  {
    id: "chase",
    institution: "Chase",
    auth: "password-mfa",
    capabilities: ["export-download", "file-drop"],
    loginUrl: "https://www.chase.com/",
    exportPath: "Account → Download account activity → CSV",
    profileId: "chase",
    verified: false,
    caveat: "chequing and card export DIFFERENT layouts; pick the ingest profile to match the account",
  },
];

export const connectorFor = (id: string): InstitutionConnector | undefined => CONNECTORS.find((c) => c.id === id);

/** Every connector offers the manual path, and it is always the last resort rather than the first. */
export function capabilitiesAreWellFormed(c: InstitutionConnector): boolean {
  return (
    c.capabilities.length > 0 &&
    c.capabilities[c.capabilities.length - 1] === "file-drop" &&
    c.capabilities.filter((x) => x === "file-drop").length === 1
  );
}

export interface ConnectionPlan {
  readonly connectorId: string;
  readonly institution: string;
  readonly action: NextAction;
  readonly capability: Capability;
  /** True when nothing automated will happen and a person has to do something. */
  readonly needsPerson: boolean;
}

/** What to do across every connection, with the blocked ones first — they are the ones that need a
 *  person, and a list that buries them under the healthy ones is a list nobody acts on. */
export function planConnections(
  connectors: readonly InstitutionConnector[],
  states: readonly ConnectionState[],
  asOf: string,
  opts: PolicyOptions = {},
): ConnectionPlan[] {
  const byId = new Map(states.map((s) => [s.connectorId, s]));
  const plans = connectors.map((c): ConnectionPlan => {
    const state = byId.get(c.id) ?? { connectorId: c.id, attempts: [], lockedOut: false };
    const action = decide(c, state, asOf, opts);
    return {
      connectorId: c.id,
      institution: c.institution,
      action,
      capability: capabilityFor(c, action),
      needsPerson: action.kind === "stop" || action.kind === "hand-to-person",
    };
  });
  return plans.sort((a, b) => Number(b.needsPerson) - Number(a.needsPerson) || a.institution.localeCompare(b.institution));
}

