import { describe, it, expect } from "vitest";
import {
  type AttemptOutcome,
  type AttemptRecord,
  type ConnectionState,
  type InstitutionConnector,
  CONNECTORS,
  backoff,
  capabilitiesAreWellFormed,
  capabilityFor,
  connectorFor,
  containsSecretBearingKey,
  decide,
  describe as describeConnection,
  lastAttempt,
  maskAccount,
  planConnections,
  sessionIsFresh,
  trailing,
} from "@/features/finance/lib/connection";

// SYNTHETIC FIXTURES ONLY. No real credential, account number or session belongs in this repo.
const NOW = "2026-07-01T12:00:00Z";
const ago = (minutes: number): string => new Date(Date.parse(NOW) - minutes * 60_000).toISOString().slice(0, 19) + "Z";

const attempt = (outcome: AttemptOutcome, minutesAgo = 60): AttemptRecord => ({ at: ago(minutesAgo), outcome });

const state = (over: Partial<ConnectionState> = {}): ConnectionState => ({
  connectorId: "discover",
  attempts: [],
  lockedOut: false,
  ...over,
});

const CONN = connectorFor("discover")!;

describe("AN AUTH FAILURE IS NEVER RETRIED", () => {
  it("stops on a rejected credential, and says why a second attempt is not free", () => {
    // One rejection can be a typo or a rotated password. A second automated attempt is how lockout
    // happens, and "I could not sync today" and "I cannot log in at all" are not the same cost.
    const a = decide(CONN, state({ attempts: [attempt("auth")] }), NOW);
    expect(a.kind).toBe("stop");
    expect(a.why).toContain("how an account gets locked");
    expect(a.why).toContain("bsc secret put");
  });

  it("stays stopped however long has passed and however fresh the session looks", () => {
    // No amount of elapsed time or session freshness may talk the policy into trying again — which
    // is why every stopping rule is checked before anything that acts.
    for (const minutesAgo of [1, 60, 60 * 24 * 30]) {
      const a = decide(
        CONN,
        state({ attempts: [attempt("auth", minutesAgo)], sessionSince: ago(1) }),
        NOW,
      );
      expect(a.kind).toBe("stop");
    }
  });

  it("RETRIES a transport failure, because that says nothing about the credential", () => {
    // The distinction between "the credential was rejected" and "the institution was not reached"
    // is the whole point of this module. Collapsing them into "it failed" loses the only fact that
    // decides whether trying again is safe.
    const a = decide(CONN, state({ attempts: [attempt("transport")] }), NOW);
    expect(a.kind).toBe("wait");
  });

  it("backs off further the more consecutive transport failures there are", () => {
    const one = decide(CONN, state({ attempts: [attempt("transport")] }), NOW);
    const three = decide(
      CONN,
      state({ attempts: [attempt("transport", 3), attempt("transport", 2), attempt("transport", 1)] }),
      NOW,
    );
    expect(one.kind).toBe("wait");
    expect(three.kind).toBe("wait");
    if (one.kind === "wait" && three.kind === "wait") {
      expect(three.untilMinutes).toBeGreaterThan(one.untilMinutes);
      expect(three.why).toContain("conspicuous");
    }
  });

  it("counts only the CONSECUTIVE trailing failures, so an old one does not compound forever", () => {
    const s = state({ attempts: [attempt("transport", 5), attempt("ok", 4), attempt("transport", 1)] });
    expect(trailing(s, "transport")).toBe(1);
    expect(lastAttempt(s)!.outcome).toBe("transport");
  });

  it("doubles and then caps", () => {
    expect(backoff(1, 5, 240)).toBe(5);
    expect(backoff(2, 5, 240)).toBe(10);
    expect(backoff(4, 5, 240)).toBe(40);
    expect(backoff(99, 5, 240)).toBe(240);
    expect(backoff(0, 5, 240)).toBe(5);
  });
});

describe("MFA is a handoff, not an obstacle to route around", () => {
  it("hands a challenge to the person rather than trying anything", () => {
    const a = decide(CONN, state({ attempts: [attempt("challenge")] }), NOW);
    expect(a.kind).toBe("hand-to-person");
    // Attempting to defeat a challenge is futile AND is itself the signal that flags a session.
    expect(a.why).toContain("gets a session flagged");
  });

  it("offers the manual path as the thing to do instead", () => {
    const a = decide(CONN, state({ attempts: [attempt("challenge")] }), NOW);
    expect(a.kind === "hand-to-person" && a.instead).toBe("file-drop");
    expect(capabilityFor(CONN, a)).toBe("file-drop");
  });

  it("stops on a changed layout instead of scraping plausible nonsense", () => {
    const a = decide(CONN, state({ attempts: [attempt("layout")] }), NOW);
    expect(a.kind).toBe("stop");
    expect(a.why).toContain("reads plausible nonsense");
  });

  it("stops on a locked account and does not pretend anything here can clear it", () => {
    for (const s of [state({ lockedOut: true }), state({ attempts: [attempt("locked")] })]) {
      const a = decide(CONN, s, NOW);
      expect(a.kind).toBe("stop");
      expect(a.why).toMatch(/institution|call to the institution/);
    }
  });
});

describe("a fresh session is the lockout-avoidance mechanism", () => {
  it("uses a young session rather than logging in at all", () => {
    const a = decide(CONN, state({ sessionSince: ago(60), attempts: [attempt("ok", 60)] }), NOW);
    expect(a.kind).toBe("use-session");
    expect(a.why).toContain("avoiding the login is what avoids the challenge");
  });

  it("logs in once the session has aged past its ttl", () => {
    const old = state({ sessionSince: ago(60 * 24 * 30), attempts: [] });
    expect(sessionIsFresh(old, NOW, 168)).toBe(false);
    expect(decide(CONN, old, NOW).kind).toBe("login");
  });

  it("treats a session dated in the future as not fresh rather than eternally fresh", () => {
    // A clock skew or a bad write should fail CLOSED. "Fresh forever" would silently stop
    // re-authenticating and every fetch after it would quietly return nothing.
    const skewed = state({ sessionSince: "2027-01-01T00:00:00Z" });
    expect(sessionIsFresh(skewed, NOW, 168)).toBe(false);
    expect(decide(CONN, skewed, NOW).kind).toBe("login");
  });

  it("will not log in twice in quick succession", () => {
    const a = decide(CONN, state({ attempts: [attempt("ok", 2)] }), NOW);
    expect(a.kind).toBe("wait");
    expect(a.why).toContain("draws attention");
  });

  it("logs in when there is no session, nothing blocking and the cooldown has passed", () => {
    const a = decide(CONN, state({ attempts: [attempt("ok", 600)] }), NOW);
    expect(a.kind).toBe("login");
  });

  it("logs in on a connection that has never been used", () => {
    expect(decide(CONN, state(), NOW).kind).toBe("login");
  });
});

describe("the manual path is never removed", () => {
  it("every packaged connector ends in file-drop, exactly once", () => {
    // Every automated path against a site somebody else controls will break, usually without
    // warning. A system that only works while the automation works is a system that stops working.
    for (const c of CONNECTORS) {
      expect(capabilitiesAreWellFormed(c)).toBe(true);
      expect(c.capabilities).toContain("file-drop");
      expect(c.capabilities[c.capabilities.length - 1]).toBe("file-drop");
    }
  });

  it("prefers the institution's own export over scraping the page", () => {
    // The export file is a contract they maintain. The DOM is not, and a scrape is far more visible
    // to whatever watches for automation.
    for (const c of CONNECTORS) {
      expect(c.capabilities[0]).toBe("export-download");
      expect(c.capabilities).not.toContain("dom-scrape");
    }
  });

  it("says every connector is UNVERIFIED and names what to expect", () => {
    expect(CONNECTORS.every((c) => c.verified === false)).toBe(true);
    expect(CONNECTORS.every((c) => (c.caveat ?? "").length > 0)).toBe(true);
    expect(CONNECTORS.every((c) => c.exportPath.length > 0)).toBe(true);
  });

  it("expects a challenge at all four — none of them is a plain password", () => {
    expect(CONNECTORS.every((c) => c.auth === "password-mfa")).toBe(true);
  });

  it("points every connector at an ingest profile", () => {
    expect(CONNECTORS.map((c) => c.profileId).sort()).toEqual([
      "bank-of-america",
      "capital-one",
      "chase",
      "discover",
    ]);
  });
});

describe("the secret never enters this layer", () => {
  it("finds a secret-bearing key at any depth", () => {
    expect(containsSecretBearingKey({ password: "x" })).toBe("password");
    expect(containsSecretBearingKey({ a: { b: [{ apiKey: "x" }] } })).toBe("apiKey");
    expect(containsSecretBearingKey({ a: { b: { otp: "1" } } })).toBe("otp");
    expect(containsSecretBearingKey([{ token: "t" }])).toBe("token");
    expect(containsSecretBearingKey({ sessionId: "s" })).toBe("sessionId");
  });

  it("passes what is legitimately there", () => {
    expect(containsSecretBearingKey({ secretId: "discover-login", account: "a@b.c" })).toBeUndefined();
    expect(containsSecretBearingKey(CONNECTORS)).toBeUndefined();
    expect(containsSecretBearingKey(state({ attempts: [attempt("auth")] }))).toBeUndefined();
  });

  it("survives a cycle instead of recursing forever", () => {
    const a: Record<string, unknown> = {};
    a.self = a;
    expect(containsSecretBearingKey(a)).toBeUndefined();
  });

  it("is a GUARD, not a filter — it reports rather than stripping", () => {
    // Silently removing a password would let a caller keep writing the code that put one there.
    const payload = { password: "x" };
    expect(containsSecretBearingKey(payload)).toBe("password");
    expect(payload.password).toBe("x");
  });

  it("masks an account wherever a person or a log will see it", () => {
    expect(maskAccount("kevin@example.com")).toBe("k****@example.com");
    expect(maskAccount("4111111111111234")).toBe("************1234");
    expect(maskAccount("abcd")).toBe("****");
    expect(maskAccount("ab")).toBe("**");
  });

  it("never prints an unmasked account in a description", () => {
    const line = describeConnection(CONN, { secretId: "discover-login", account: "kevin@example.com" }, decide(CONN, state(), NOW));
    expect(line).not.toContain("kevin@example.com");
    expect(line).toContain("k****@example.com");
    expect(line).toContain("Discover");
  });
});

describe("planConnections — the blocked ones first", () => {
  it("puts what needs a person above what is healthy", () => {
    // A list that buries the blocked connections under the working ones is a list nobody acts on.
    const plans = planConnections(
      CONNECTORS,
      [
        { connectorId: "discover", attempts: [attempt("ok", 600)], lockedOut: false },
        { connectorId: "chase", attempts: [attempt("auth")], lockedOut: false },
        { connectorId: "capital-one", attempts: [attempt("challenge")], lockedOut: false },
      ],
      NOW,
    );
    expect(plans.slice(0, 2).map((p) => p.institution)).toEqual(["Capital One", "Chase"]);
    expect(plans.slice(0, 2).every((p) => p.needsPerson)).toBe(true);
    expect(plans.slice(2).every((p) => !p.needsPerson)).toBe(true);
  });

  it("plans a connector that has no state at all rather than skipping it", () => {
    const plans = planConnections(CONNECTORS, [], NOW);
    expect(plans).toHaveLength(CONNECTORS.length);
    expect(plans.every((p) => p.action.kind === "login")).toBe(true);
    expect(plans.every((p) => p.capability === "export-download")).toBe(true);
  });

  it("routes a blocked connector to the manual path, not to its usual capability", () => {
    const plans = planConnections(CONNECTORS, [{ connectorId: "chase", attempts: [attempt("auth")], lockedOut: false }], NOW);
    const chase = plans.find((p) => p.institution === "Chase")!;
    expect(chase.capability).toBe("file-drop");
    expect(chase.needsPerson).toBe(true);
  });

  it("carries no secret-bearing key in anything it produces", () => {
    const plans = planConnections(CONNECTORS, [{ connectorId: "chase", attempts: [attempt("auth")], lockedOut: false }], NOW);
    expect(containsSecretBearingKey(plans)).toBeUndefined();
  });
});

